(()=>{
const cities=[{id:'trondheim',name:'Trondheim',station:'Voll · SN68860',...window.TRONDHEIM_DATA},{id:'bergen',name:'Bergen',station:'Florida · SN50540',monthly:window.RAIN_DATA,daily:window.RECORD_DATA},{id:'oslo',name:'Oslo',station:'Blindern · SN18700',...window.OSLO_DATA},{id:'stavanger',name:'Stavanger-området',station:'Sviland, Sandnes · SN44800',...window.STAVANGER_DATA}];
const $=id=>document.getElementById(id),fmt=n=>Number.isFinite(n)?n.toLocaleString('nb-NO',{maximumFractionDigits:1}):'—';
let message='Lagrede målinger. Henter ferske døgn for alle stasjonene …';
function render(){const r=window.CityComparison.compare(cities),base=r.cities.find(c=>c.id===$('comparisonBase').value);const rows=(group,items)=>items.map(([key,label,unit])=>{const b=base[group][key];return '<tr><th scope="row">'+label+'</th>'+r.cities.map(c=>{const v=c[group][key],delta=v-b;return '<td><strong>'+fmt(v)+(Number.isFinite(v)?' '+unit:'')+'</strong><small>'+(c.id===base.id?'Referanse':Number.isFinite(v)&&Number.isFinite(b)?(delta>0?'+':'')+fmt(delta)+' '+unit+' mot '+base.name:'Utilstrekkelige data')+'</small></td>'}).join('')+'</tr>'}).join('');const table=(group,items)=>'<div class="table-wrap"><table><thead><tr><th>Mål</th>'+r.cities.map(c=>'<th>'+c.name+'<small>'+c.station+'</small></th>').join('')+'</tr></thead><tbody>'+rows(group,items)+'</tbody></table></div>';
$('comparisonStatus').textContent=message;
$('comparisonContent').innerHTML='<section class="panel"><p class="eyebrow">SAMME MÅLEDATOER</p><h3>2026 · hittil i år</h3><p class="small muted">1. januar–'+r.end+' · '+r.days+' av '+r.expected+' datoer har målinger i alle byene.'+(r.days<r.expected?' Ufullstendig dekning – tallene gjelder bare de felles målte døgnene.':' Full dekning i sammenligningsperioden.')+'</p>'+table('current',[['wet','Regndager','dager'],['dry','Tørre dager (under 1 mm)','dager'],['mm','Samlet nedbør','mm'],['zero','Helt nedbørfrie dager','dager'],['heavy','Kraftige nedbørdøgn (minst 20 mm)','dager'],['max','Våteste døgn','mm']])+'</section><section class="panel"><p class="eyebrow">ET NORMALÅR</p><h3>Årssnitt · 1991–2020</h3>'+table('normal',[['mm','Normalnedbør per år','mm'],['wet','Snitt regndager per år','dager'],['dry','Snitt tørre dager per år','dager'],['zero','Snitt helt nedbørfrie dager','dager'],['heavy','Snitt kraftige nedbørdøgn','dager']])+'<p class="small muted">Nedbør: alle 30 år kreves. Døgnsnitt: '+r.years.length+' felles komplette år'+(r.years.length?' ('+r.years.join(', ')+')':' – utilstrekkelige data')+'. År med manglende døgn utelates for alle byene.</p></section>';
}
async function refresh(){const button=$('comparisonRefresh');button.disabled=true;const results=await Promise.allSettled(cities.map(async c=>{const response=await fetch('/api/recent-rain?city='+c.id,{cache:'no-store'});if(!response.ok)throw Error();const data=await response.json();if(data.station!==c.daily.station||!data.dailyTenths?.length||data.last<c.daily.last)throw Error();const map=new Map(c.daily.dailyTenths.filter(([d])=>d<data.first));for(const row of data.dailyTenths)map.set(...row);c.daily={...c.daily,...data,dailyTenths:[...map].sort((a,b)=>a[0].localeCompare(b[0]))}}));message=results.every(r=>r.status==='fulfilled')?'Oppdatert fra MET Frost.':'Kunne ikke hente alle byene. Lagrede målinger beholdes der oppdateringen feilet.';message+=' Siste måledato: '+cities.map(c=>c.name+' '+c.daily.last).join(' · ');button.disabled=false;render()}
$('comparisonBase').onchange=render;$('comparisonRefresh').onclick=refresh;render();refresh();
})();
